diff --git i/internal/ui/containers/model.go w/internal/ui/containers/model.go
index a1a72807..7dcaf2f7 100644
--- i/internal/ui/containers/model.go
+++ w/internal/ui/containers/model.go
@@ -37,6 +37,8 @@ type Model struct {
 	containerTable datatable.Model[docker.Container]
 	spinner        spinner.Model
 	loading        bool
+	// unfocused is true while the terminal is blurred: the tick skips its read.
+	unfocused bool
 	// footer is the one line of transient state below the viewport (Rule 128).
 	footer       sharedcomponents.FooterMessage
 	confirmModal *sharedcomponents.ConfirmModal
diff --git i/internal/ui/containers/update.go w/internal/ui/containers/update.go
index 9a7cbbe1..743914b0 100644
--- i/internal/ui/containers/update.go
+++ w/internal/ui/containers/update.go
@@ -13,6 +13,7 @@ import (
 	tea "charm.land/bubbletea/v2"
 	"github.com/anthnel/devdesk/internal/docker"
 	"github.com/anthnel/devdesk/internal/engine"
+	"github.com/anthnel/devdesk/internal/shared"
 	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
 	"github.com/anthnel/devdesk/internal/ui/keymap"
 	ociresources "github.com/anthnel/devdesk/internal/ui/oci_resources"
@@ -65,8 +66,16 @@ func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 		// The next tick is requested here: a tick that does not re-arm itself
 		// refreshes once, two seconds after Init, and never again — which is
 		// what made ctrl+r the only way to see the gauges move.
+		if m.unfocused {
+			// Blurred terminal: keep the chain alive, skip the read. The
+			// focus edge reads once (DEVDESK-210).
+			return m, tickCmd()
+		}
 		return m, tea.Batch(tickCmd(), fetchContainers(), fetchMetrics())

+	case shared.TerminalFocusMsg:
+		return m.setTerminalFocus(msg)
+
 	case ContainersListMsg:
 		return m.handleContainersList(msg)

@@ -682,3 +691,14 @@ func (m *Model) resize(width, height int) {
 	// component's rather than ten percentages written out here.
 	m.containerTable.Resize(width, height-2)
 }
+
+// setTerminalFocus records whether the terminal has the focus. On the edge that
+// follows a blur it reads the list and the metrics once, without a new tick:
+// the chain kept running while blurred (DEVDESK-210).
+func (m Model) setTerminalFocus(msg shared.TerminalFocusMsg) (tea.Model, tea.Cmd) {
+	m.unfocused = !msg.Focused
+	if msg.Focused && msg.Resume {
+		return m, tea.Batch(fetchContainers(), fetchMetrics())
+	}
+	return m, nil
+}
diff --git i/internal/ui/netdiag/ports_model.go w/internal/ui/netdiag/ports_model.go
index 0fd431f4..614d443a 100644
--- i/internal/ui/netdiag/ports_model.go
+++ w/internal/ui/netdiag/ports_model.go
@@ -12,6 +12,7 @@ import (
 	"charm.land/lipgloss/v2"

 	"github.com/anthnel/devdesk/internal/ports"
+	"github.com/anthnel/devdesk/internal/shared"
 	"github.com/anthnel/devdesk/internal/ui/components"
 	"github.com/anthnel/devdesk/internal/ui/datatable"
 	"github.com/anthnel/devdesk/internal/ui/indicator"
@@ -99,6 +100,9 @@ type PortsModel struct {
 	table datatable.Model[ports.Socket]

 	paused bool
+	// unfocused is true while the terminal is blurred. It is separate from
+	// paused, which is the user's own choice and shows in the bar.
+	unfocused bool

 	// address display
 	// numericAddrs true shows addresses as the system reports them; false asks
@@ -268,6 +272,8 @@ func (pm *PortsModel) update(msg tea.Msg) (*PortsModel, tea.Cmd) {
 	switch msg := msg.(type) {
 	case portsTickMsg:
 		return pm.handleTick()
+	case shared.TerminalFocusMsg:
+		return pm.setTerminalFocus(msg)
 	case portsDataMsg:
 		return pm.handleData(msg)
 	case portsKillResultMsg:
@@ -287,12 +293,22 @@ func (pm *PortsModel) update(msg tea.Msg) (*PortsModel, tea.Cmd) {
 }

 func (pm *PortsModel) handleTick() (*PortsModel, tea.Cmd) {
-	if pm.paused {
+	if pm.paused || pm.unfocused {
 		return pm, portsTickCmd(pm.refresh)
 	}
 	return pm, tea.Batch(fetchPortsCmd(pm.numericAddrs), portsTickCmd(pm.refresh))
 }

+// setTerminalFocus records the focus. On the edge after a blur it reads once,
+// with no new tick (the chain kept running), unless the user paused the poll.
+func (pm *PortsModel) setTerminalFocus(msg shared.TerminalFocusMsg) (*PortsModel, tea.Cmd) {
+	pm.unfocused = !msg.Focused
+	if msg.Focused && msg.Resume && !pm.paused {
+		return pm, fetchPortsCmd(pm.numericAddrs)
+	}
+	return pm, nil
+}
+
 func (pm *PortsModel) handleData(msg portsDataMsg) (*PortsModel, tea.Cmd) {
 	if msg.err != nil {
 		log.Printf("ERROR [netdiag/ports] ports.List: %v", msg.err)
diff --git i/internal/ui/netdiag/update.go w/internal/ui/netdiag/update.go
index 8ab15de4..faed8e99 100644
--- i/internal/ui/netdiag/update.go
+++ w/internal/ui/netdiag/update.go
@@ -10,6 +10,7 @@ import (
 	"github.com/anthnel/devdesk/internal/forward"
 	"github.com/anthnel/devdesk/internal/jobs"
 	"github.com/anthnel/devdesk/internal/netcheck"
+	"github.com/anthnel/devdesk/internal/shared"
 	"github.com/anthnel/devdesk/internal/ui/components"
 	"github.com/anthnel/devdesk/internal/ui/keymap"
 )
@@ -99,6 +100,13 @@ func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
 		m.portsModel, cmd = m.portsModel.update(msg)
 		return m, cmd

+	// The terminal focus reaches the ports poll on every tab: its tick runs
+	// whichever tab shows.
+	case shared.TerminalFocusMsg:
+		var cmd tea.Cmd
+		m.portsModel, cmd = m.portsModel.update(msg)
+		return m, cmd
+
 	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
 	// before dropping the connections a redirection is carrying — so the answer
 	// goes to the tab that asked rather than to Ports unconditionally, which

