func (m *Model) FilterBarVisible() bool {
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.table.FilterBar().IsVisible()
	case tabForward:
		return m.forwardModel.table.FilterBar().IsVisible()
	}
	return m.activeTab == tabDiagnostics && m.filterBar.IsVisible()
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		return m, nil

	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)

	// The router's animation frame: only the blink phase of the Ports dot. The
	// footers keep their own spinner chains.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
